function base64ToBytes(value) {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

const FALLBACK_IMAGES = Object.fromEntries(
  Object.entries(FALLBACK_IMAGE_DATA).map(([key, value]) => [
    key,
    base64ToBytes(value)
  ])
);


const KONACHAN_ENDPOINT = 'https://konachan.net/post.json';
const KONACHAN_TAGS = 'scenic no_humans rating:safe';
const HUMAN_TAGS = new Set([
  '1girl',
  '1boy',
  '2girls',
  '2boys',
  'multiple_girls',
  'multiple_boys',
  'girl',
  'boy',
  'male',
  'female',
  'man',
  'woman',
  'people',
  'person',
  'child',
  'children',
  'character',
  'cosplay',
  'portrait',
  'face',
  'solo',
  'group',
  'couple'
]);

const UPSTREAM_UA =
  'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 ' +
  '(KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36';

const MIN_DIMENSION = 200;
const MAX_DIMENSION = 3840;
const API_TIMEOUT_MS = 12_000;
const IMAGE_TIMEOUT_MS = 18_000;
const IMAGE_ATTEMPT_BUDGET_MS = 24_000;

// 上游全部失败时返回内嵌 PNG 占位图，避免 <img> 直接显示 502 JSON。
const NO_CACHE_HEADERS = {
  'Cache-Control': 'no-store, no-cache, must-revalidate, max-age=0',
  'CDN-Cache-Control': 'no-store',
  'Cloudflare-CDN-Cache-Control': 'no-store',
  Pragma: 'no-cache',
  Expires: '0'
};

const CORS_HEADERS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, HEAD, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type',
  'Access-Control-Expose-Headers':
    'X-Image-Provider, X-Image-Id, X-Image-Page, X-Image-Source, ' +
    'X-Image-Width, X-Image-Height, X-Target-Width, X-Target-Height, ' +
    'X-Image-Resized, X-Image-Fallback',
  'Access-Control-Max-Age': '86400'
};

function baseHeaders(extra = {}) {
  return {
    ...CORS_HEADERS,
    ...NO_CACHE_HEADERS,
    'Accept-CH':
      'Sec-CH-UA-Mobile, Sec-CH-UA-Platform, Sec-CH-Viewport-Width, ' +
      'Sec-CH-Viewport-Height, Sec-CH-DPR, DPR',
    'Cross-Origin-Resource-Policy': 'cross-origin',
    'X-Content-Type-Options': 'nosniff',
    Vary:
      'User-Agent, Sec-CH-UA-Mobile, Sec-CH-UA-Platform, ' +
      'Sec-CH-Viewport-Width, Sec-CH-Viewport-Height, Sec-CH-DPR, DPR',
    ...extra
  };
}

function jsonResponse(payload, status = 200) {
  return new Response(JSON.stringify(payload), {
    status,
    headers: baseHeaders({
      'Content-Type': 'application/json; charset=utf-8'
    })
  });
}

function headerSafe(value) {
  return String(value || '').replace(/[^\x20-\x7E]/g, '');
}

function clampDimension(value) {
  const n = Number.parseInt(value, 10);
  if (!Number.isFinite(n) || n <= 0) return 0;
  return Math.min(MAX_DIMENSION, Math.max(MIN_DIMENSION, n));
}

function deviceDefaults(request) {
  const ua = request.headers.get('user-agent') || '';
  const cfDevice = (request.headers.get('cf-device-type') || '').toLowerCase();
  const uaMobile = request.headers.get('sec-ch-ua-mobile') || '';
  const platform = (request.headers.get('sec-ch-ua-platform') || '')
    .replace(/"/g, '')
    .toLowerCase();

  const mobile = { w: 720, h: 1280, orientation: 'portrait' };
  const tablet = { w: 800, h: 1200, orientation: 'portrait' };
  const desktop = { w: 1920, h: 1080, orientation: 'landscape' };

  if (cfDevice === 'mobile') return mobile;
  if (cfDevice === 'tablet') return tablet;
  if (cfDevice === 'desktop') return desktop;

  if (uaMobile === '?1') return mobile;

  if (platform === 'ipados') return tablet;
  if (platform === 'ios') return mobile;
  if (platform === 'android') {
    if (uaMobile === '?0') return tablet;
  }
  if (['windows', 'macos', 'linux', 'chrome os', 'chromium os'].includes(platform)) {
    return desktop;
  }

  // Check tablets before phones: some Android tablets contain "Mobile".
  const androidTablet = /Android/i.test(ua) && !/Mobile/i.test(ua);
  if (
    androidTablet ||
    /iPad|Tablet|PlayBook|Silk|Kindle|Nexus 7|Nexus 10|KFAPWI|SM-T|GT-P|Lenovo Tab|Galaxy Tab|Xoom|Transformer/i.test(ua)
  ) {
    return tablet;
  }

  if (
    /Mobile|Android|iPhone|iPod|IEMobile|Opera Mini|Windows Phone|BlackBerry|BB10|webOS/i.test(ua)
  ) {
    return mobile;
  }

  return desktop;
}

function orientationOf(w, h) {
  if (w === h) return 'square';
  return w > h ? 'landscape' : 'portrait';
}

function resolveTarget(request, url) {
  const requested = (url.searchParams.get('orientation') || '').toLowerCase();
  const forcedOrientation = ['portrait', 'landscape', 'square'].includes(requested)
    ? requested
    : '';

  const qw = clampDimension(url.searchParams.get('w'));
  const qh = clampDimension(url.searchParams.get('h'));

  if (qw && qh) {
    return { w: qw, h: qh, orientation: orientationOf(qw, qh) };
  }

  const defaults = deviceDefaults(request);

  // Prefer the real viewport when the browser sends Client Hints.
  if (!qw && !qh && !forcedOrientation) {
    const vw = Number(
      request.headers.get('sec-ch-viewport-width') ||
        request.headers.get('viewport-width')
    );
    const vh = Number(
      request.headers.get('sec-ch-viewport-height') ||
        request.headers.get('viewport-height')
    );
    const rawDpr =
      Number(
        request.headers.get('sec-ch-dpr') || request.headers.get('dpr')
      ) || 1;
    const dpr = Math.min(Math.max(rawDpr, 1), 2);

    if (vw > 0 || vh > 0) {
      let w = vw > 0 ? Math.round(vw * dpr) : 0;
      let h = vh > 0 ? Math.round(vh * dpr) : 0;

      if (!w && h) {
        w = Math.round(
          h * (defaults.orientation === 'portrait' ? 9 / 16 : 16 / 9)
        );
      } else if (w && !h) {
        h = Math.round(
          w * (defaults.orientation === 'portrait' ? 16 / 9 : 9 / 16)
        );
      }

      w = clampDimension(w);
      h = clampDimension(h);

      if (w && h) {
        return { w, h, orientation: orientationOf(w, h) };
      }
    }
  }

  const orientation = forcedOrientation || defaults.orientation;

  let w;
  let h;

  if (qw && !qh) {
    w = qw;
    h = Math.round(
      qw *
        (orientation === 'portrait' ? 16 / 9 : orientation === 'square' ? 1 : 9 / 16)
    );
  } else if (!qw && qh) {
    h = qh;
    w = Math.round(
      qh *
        (orientation === 'portrait' ? 9 / 16 : orientation === 'square' ? 1 : 16 / 9)
    );
  } else if (forcedOrientation) {
    [w, h] =
      orientation === 'portrait'
        ? [720, 1280]
        : orientation === 'square'
          ? [1080, 1080]
          : [1920, 1080];
  } else {
    w = defaults.w;
    h = defaults.h;
  }

  w = clampDimension(w);
  h = clampDimension(h);

  if (!w || !h) {
    w = defaults.w;
    h = defaults.h;
  }

  return { w, h, orientation: orientationOf(w, h) };
}

async function fetchJson(urlString) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), API_TIMEOUT_MS);

  try {
    const response = await fetch(urlString, {
      signal: controller.signal,
      headers: {
        'User-Agent': UPSTREAM_UA,
        Accept: 'application/json,text/plain,*/*'
      },
      // Do not let Cloudflare cache upstream metadata.
      cf: { cacheEverything: false, cacheTtl: 0 }
    });

    if (!response.ok) {
      throw new Error(`upstream HTTP ${response.status}`);
    }

    return await response.json();
  } finally {
    clearTimeout(timer);
  }
}

async function getKonachanPool(target) {
  const api = new URL(KONACHAN_ENDPOINT);
  api.searchParams.set('tags', KONACHAN_TAGS);
  api.searchParams.set('limit', '100');
  api.searchParams.set('_', String(Date.now()));

  const data = await fetchJson(api.toString());
  if (!Array.isArray(data)) return [];

  const usable = data.filter((item) => {
    if (!item || !item.file_url || !item.width || !item.height) return false;
    const tags = String(item.tags || '').toLowerCase().split(/\s+/);
    if (!tags.includes('scenic')) return false;
    if (!tags.includes('no_humans')) return false;
    if (tags.some((tag) => HUMAN_TAGS.has(tag))) return false;
    return !tags.includes('watermark');
  });

  const dimensionMatched = usable.filter((item) => {
    if (target.orientation === 'portrait') {
      return Number(item.height) >= target.h * 0.75;
    }
    if (target.orientation === 'landscape') {
      return Number(item.width) >= target.w * 0.75;
    }
    return Math.min(Number(item.width), Number(item.height)) >=
      Math.min(target.w, target.h) * 0.75;
  });

  const pool = dimensionMatched.length ? dimensionMatched : usable;

  return pool.map((item) => {
    const page = `https://konachan.net/post/show/${item.id}`;
    return {
      provider: 'konachan',
      id: String(item.id),
      imageUrl: item.file_url,
      original: item.file_url,
      width: Number(item.width) || 0,
      height: Number(item.height) || 0,
      page,
      source: item.source || page
    };
  });
}

function buildResized(item, w, h) {
  const source = encodeURIComponent(item.imageUrl);
  return (
    `https://wsrv.nl/?url=${source}` +
    `&w=${w}&h=${h}&fit=cover&a=attention&output=webp&q=85`
  );
}

function pickRandom(pool, count) {
  const copy = pool.slice();

  for (let i = copy.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }

  return copy.slice(0, Math.max(1, count));
}

async function selectItem(target) {
  try {
    const konachan = await getKonachanPool(target);
    if (konachan.length) {
      const item = pickRandom(konachan, 1)[0];
      return { ...item, resized: buildResized(item, target.w, target.h) };
    }
  } catch (error) {
    console.error('Konachan failed:', error);
  }

  return null;
}

async function fetchImage(urlString, timeoutMs = IMAGE_TIMEOUT_MS) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), Math.max(1000, timeoutMs));

  try {
    const response = await fetch(urlString, {
      signal: controller.signal,
      redirect: 'follow',
      headers: {
        'User-Agent': UPSTREAM_UA,
        Accept: 'image/avif,image/webp,image/png,image/jpeg,image/*,*/*;q=0.8'
      },
      cf: { cacheEverything: false, cacheTtl: 0 }
    });

    if (!response.ok) {
      if (response.body) await response.body.cancel();
      return null;
    }

    const contentType = (response.headers.get('content-type') || '')
      .split(';')[0]
      .trim()
      .toLowerCase();

    if (!contentType.startsWith('image/')) {
      if (response.body) await response.body.cancel();
      return null;
    }

    return { response, contentType };
  } finally {
    clearTimeout(timer);
  }
}

async function fetchRandomImage(target) {
  const providers = [
    { name: 'konachan', load: getKonachanPool, attempts: 4 }
  ];
  const deadline = Date.now() + IMAGE_ATTEMPT_BUDGET_MS;
  const failures = [];

  for (const provider of providers) {
    if (Date.now() >= deadline) {
      failures.push(`${provider.name}: total budget exhausted`);
      break;
    }

    let pool;

    try {
      pool = await provider.load(target);
    } catch (error) {
      failures.push(`${provider.name}: pool ${error.message}`);
      console.error(`${provider.name} pool failed:`, error);
      continue;
    }

    if (!pool.length) {
      failures.push(`${provider.name}: empty pool`);
      continue;
    }

    for (const item of pickRandom(pool, provider.attempts)) {
      if (Date.now() >= deadline) break;

      const resized = buildResized(item, target.w, target.h);
      const candidates = resized === item.original ? [resized] : [resized, item.original];

      for (const candidate of candidates) {
        if (Date.now() >= deadline) break;

        try {
          const remaining = Math.max(2000, deadline - Date.now());
          const image = await fetchImage(candidate, Math.min(IMAGE_TIMEOUT_MS, remaining));
          if (image) {
            return {
              item,
              resized: candidate,
              response: image.response,
              contentType: image.contentType
            };
          }
          failures.push(`${provider.name}: no image ${item.id}`);
        } catch (error) {
          failures.push(`${provider.name}: image ${item.id} ${error.message}`);
          console.error(`${provider.name} image failed:`, error);
        }
      }
    }
  }

  console.error('No image available:', failures.slice(0, 12));
  return null;
}

function extensionFor(contentType) {
  if (contentType === 'image/webp') return '.webp';
  if (contentType === 'image/jpeg') return '.jpg';
  if (contentType === 'image/png') return '.png';
  if (contentType === 'image/avif') return '.avif';
  if (contentType === 'image/gif') return '.gif';
  return '.img';
}

function imageHeaders(item, target, contentType, isResized) {
  return baseHeaders({
    'Content-Type': contentType,
    'Content-Disposition': `inline; filename="random-scenery${extensionFor(contentType)}"`,
    'X-Image-Provider': item.provider,
    'X-Image-Id': headerSafe(item.id),
    'X-Image-Page': headerSafe(item.page),
    'X-Image-Source': headerSafe(item.source),
    'X-Image-Width': String(item.width || ''),
    'X-Image-Height': String(item.height || ''),
    'X-Target-Width': String(target.w),
    'X-Target-Height': String(target.h),
    'X-Image-Resized': isResized ? '1' : '0',
    'X-Image-Fallback': '0'
  });
}

function fallbackPngFor(target) {
  if (target.orientation === 'square') return FALLBACK_IMAGES.square;
  if (target.orientation === 'landscape') return FALLBACK_IMAGES.landscape;
  return target.w / target.h >= 0.62
    ? FALLBACK_IMAGES.tablet
    : FALLBACK_IMAGES.mobile;
}

function fallbackImageResponse(target) {
  const bytes = fallbackPngFor(target);

  return new Response(bytes, {
    status: 200,
    headers: baseHeaders({
      'Content-Type': 'image/png',
      'Content-Disposition': 'inline; filename="random-scenery-fallback.png"',
      'X-Image-Provider': 'fallback',
      'X-Image-Id': 'fallback',
      'X-Image-Fallback': '1',
      'X-Target-Width': String(target.w),
      'X-Target-Height': String(target.h)
    })
  });
}


export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    if (request.method === 'OPTIONS') {
      return new Response(null, { status: 204, headers: baseHeaders() });
    }

    if (url.pathname === '/health') {
      if (request.method === 'HEAD') {
        return new Response(null, {
          status: 200,
          headers: baseHeaders({ 'Content-Type': 'application/json; charset=utf-8' })
        });
      }

      return jsonResponse({
        ok: true,
        time: new Date().toISOString(),
        upstreams: ['konachan']
      });
    }

    if (request.method !== 'GET' && request.method !== 'HEAD') {
      return jsonResponse(
        { code: 405, error: 'METHOD_NOT_ALLOWED', message: 'Only GET, HEAD and OPTIONS are supported.' },
        405
      );
    }

    const target = resolveTarget(request, url);
    const format = (url.searchParams.get('format') || 'image').toLowerCase();

    if (!['image', 'json', 'redirect'].includes(format)) {
      return jsonResponse(
        { code: 400, error: 'INVALID_FORMAT', message: 'format must be image, json or redirect.' },
        400
      );
    }

    if (request.method === 'HEAD') {
      return new Response(null, {
        status: 200,
        headers: baseHeaders({
          'Content-Type': format === 'json' ? 'application/json; charset=utf-8' : 'image/jpeg',
          'X-Target-Width': String(target.w),
          'X-Target-Height': String(target.h)
        })
      });
    }

    if (format === 'json') {
      const item = await selectItem(target);

      if (!item) {
        return jsonResponse(
          { code: 502, error: 'UPSTREAM_UNAVAILABLE', message: 'No image available right now.' },
          502
        );
      }

      return jsonResponse({
        code: 200,
        provider: item.provider,
        id: item.id,
        width: target.w,
        height: target.h,
        originalWidth: item.width,
        originalHeight: item.height,
        url: item.resized,
        original: item.original,
        page: item.page,
        source: item.source
      });
    }

    if (format === 'redirect') {
      const item = await selectItem(target);

      if (!item) {
        return jsonResponse(
          { code: 502, error: 'UPSTREAM_UNAVAILABLE', message: 'No image available right now.' },
          502
        );
      }

      return new Response(null, {
        status: 302,
        headers: baseHeaders({
          Location: item.resized,
          'X-Image-Provider': item.provider,
          'X-Image-Id': headerSafe(item.id),
          'X-Image-Page': headerSafe(item.page),
          'X-Image-Source': headerSafe(item.source),
          'X-Target-Width': String(target.w),
          'X-Target-Height': String(target.h)
        })
      });
    }

    const result = await fetchRandomImage(target);

    if (!result) {
      return fallbackImageResponse(target);
    }

    const { item, resized, response, contentType } = result;
    const isResized = resized !== item.original;

    return new Response(response.body, {
      status: 200,
      headers: imageHeaders(item, target, contentType, isResized)
    });
  }
};
